mapper.select:
select pc.id, pc.sku_id as skuId, pd.sku_no as skuNo, pd.name as skuName, pc.certificate_valid_time as certificateValidTime, pc.type, pc.dict_project as dictProject, att.attach_name as attachName, att.attach_url as attachUrl, pc.remark, pc.update_user_name as updateUserName, pc.update_time as updateTime from product_certificate pc inner join product_detail pd on pc.sku_id = pd.id and pd.is_deleted = false inner join ( select business_id,attach_name,attach_url from attachment where id in ( select max(id) from attachment where is_deleted = false group by business_id ) ) att on pc.id = att.business_id
pc.is_deleted = false
and pd.name ILIKE concat('%',#{params.skuName}::text,'%')
and att.attach_name ILIKE concat('%',#{params.attachName}::text,'%')
and pc.remark ILIKE concat('%',#{params.remark}::text,'%')
and pd.sku_no in
#{item}
and pc.type in
#{item}
and pc.dict_project in
#{item}
and pc.certificate_valid_time >= #{params.certificateValidTimeList[0]} and (#{params.certificateValidTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > pc.certificate_valid_time
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
pc.update_time desc

